\set ON_ERROR_STOP on
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(command text,expected text,label text)returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>expected then raise exception 'FAIL: % expected % got % (%)',label,expected,sqlstate,sqlerrm;end if;raise notice 'PASS: %',label;return;end;raise exception 'FAIL: % unexpectedly succeeded',label;end;$$;
select pg_temp.check_true((select not prosecdef and provolatile='s'and proconfig @> array['search_path=""']from pg_proc where oid='public.read_update_recipients_export(uuid,uuid,text)'::regprocedure),'export stable invoker with empty search path');
select pg_temp.check_true(has_function_privilege('authenticated','public.read_update_recipients_export(uuid,uuid,text)','execute')and not has_function_privilege('anon','public.read_update_recipients_export(uuid,uuid,text)','execute')and not has_function_privilege('service_role','public.read_update_recipients_export(uuid,uuid,text)','execute'),'permissive public execute defaults neutralized');
create function pg_temp.export(status text default'all')returns jsonb language sql as $$select public.read_update_recipients_export('88000000-0000-4000-8000-000000000001',(select id from public.updates_posts where title='Synthetic export announcement'),status)$$;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
select pg_temp.check_true(pg_temp.export()->>'matchedCount'='500'and jsonb_array_length(pg_temp.export()->'recipients')=500,'complete500 export independent displayed50rows');
select pg_temp.check_true(pg_temp.export()->'counts'='{"total":500,"viewed":300,"confirmed":200}'::jsonb,'one snapshot coherent exact prefilter counts');
select pg_temp.check_true(pg_temp.export('viewed')->>'matchedCount'='300'and pg_temp.export('unviewed')->>'matchedCount'='200'and pg_temp.export('confirmed')->>'matchedCount'='200'and pg_temp.export('unconfirmed')->>'matchedCount'='300','all four selected status subsets complete');
select pg_temp.check_true(pg_temp.export('viewed')->'recipients'->0->>'viewedAt'='2026-10-03T21:10:00.123456Z'and pg_temp.export('confirmed')->'recipients'->0->>'confirmedAt'='2026-10-03T21:10:01.654321Z','UTC export preserves original six microseconds');
select pg_temp.check_true(length(pg_temp.export()->'recipients'->0->>'name')=100,'retained suspendedrecipient Unicode name exported without roster filter');
select pg_temp.check_true(not(pg_temp.export()->'recipients'->0?'body')and not(pg_temp.export()->'recipients'->0?'email')and not(pg_temp.export()->'recipients'->0?'phone'),'private notes/commentbody/contact fields excluded');
select pg_temp.expect_error($q$select pg_temp.export('bad')$q$,'22023','invalid status rejected');
select pg_temp.expect_error($q$select pg_temp.export(null)$q$,'22023','null status rejected');
select pg_temp.expect_error($q$select public.read_update_recipients_export('88000000-0000-4000-8000-000000000002',(select id from public.updates_posts where title='Synthetic export announcement'))$q$,'42501','tenant-bound post prevents foreign export');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000902',false);
select pg_temp.check_true(pg_temp.export()->>'role'='admin'and pg_temp.export()->>'matchedCount'='500','current nonrecipient admin management export permitted');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000903',false);
select pg_temp.expect_error($q$select pg_temp.export()$q$,'42501','manager cannot export');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8001-000000000002',false);
