reset role;update public.tenant_memberships set status='active'where user_id='00000000-0000-4000-8000-000000000901';update public.tenants set status='suspended'where id='88000000-0000-4000-8000-000000000001';set role authenticated;
select pg_temp.expect_error($q$select pg_temp.export()$q$,'42501','current company suspension denies');
